package com.greatleyposhley.professy.collaboration;

import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.beans.factory.annotation.Value;
import tools.jackson.databind.ObjectMapper;
import java.util.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import static com.greatleyposhley.professy.collaboration.WorkAccess.number;

/** A short-lived meeting credential never grants a bot a human account or general workspace access. */
@RestController
public class MeetingRuntime {
 private final JdbcTemplate jdbc; private final WorkAccess access; private final ObjectMapper json; private final String ice;
 public MeetingRuntime(JdbcTemplate jdbc, WorkAccess access, ObjectMapper json, @Value("${app.meetings.ice-servers:[]}") String ice){this.jdbc=jdbc;this.access=access;this.json=json;this.ice=ice;}
 static String digest(String token){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException error){throw new IllegalStateException(error);}}
 private void organizer(long room,long agent){
  access.require("MEETINGS.UPDATE");var user=access.actor();
  var rows=jdbc.queryForList("SELECT m.id FROM workspace_meetings m JOIN workspace_meeting_members p ON p.meeting_id=m.id AND p.participant_id=? JOIN workspace_actors a ON a.id=? AND a.org_id=m.org_id AND a.actor_type='AGENT' AND a.status='ACTIVE' WHERE m.id=? AND m.org_id=? AND m.owner_id=? AND m.status NOT IN ('ENDED','CANCELLED')",-agent,agent,room,user.getOrgId(),user.getId());
  if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the organizer can connect an invited active agent");
 }
 @PostMapping("/api/workspace/meetings/{room}/agents/{agent}/sessions") @Transactional
 public Object issue(@PathVariable long room,@PathVariable long agent){
  organizer(room,agent);byte[] random=new byte[32];new SecureRandom().nextBytes(random);String token="gp_meeting_"+Base64.getUrlEncoder().withoutPadding().encodeToString(random);
  jdbc.update("DELETE FROM workspace_meeting_agent_sessions WHERE meeting_id=? AND agent_id=?",room,agent);
  jdbc.update("INSERT INTO workspace_meeting_agent_sessions(token_hash,meeting_id,agent_id,org_id,created_by,expires_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP+INTERVAL 2 HOUR)",digest(token),room,agent,access.actor().getOrgId(),access.actor().getId());
  return Map.of("token",token,"meetingId",room,"agentId",agent,"expiresIn",7200);
 }
 @DeleteMapping("/api/workspace/meetings/{room}/agents/{agent}/sessions") @Transactional
 public void revoke(@PathVariable long room,@PathVariable long agent){organizer(room,agent);jdbc.update("DELETE FROM workspace_meeting_agent_sessions WHERE meeting_id=? AND agent_id=?",room,agent);jdbc.update("UPDATE workspace_meeting_members SET last_seen=NULL WHERE meeting_id=? AND participant_id=?",room,-agent);}
 private Map<String,Object> session(String bearer,Long room){
  if(bearer==null||!bearer.matches("Bearer gp_meeting_[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"A meeting agent session is required");
  var rows=jdbc.queryForList("SELECT s.*,a.display_name FROM workspace_meeting_agent_sessions s JOIN workspace_actors a ON a.id=s.agent_id AND a.org_id=s.org_id AND a.actor_type='AGENT' AND a.status='ACTIVE' JOIN workspace_meetings m ON m.id=s.meeting_id AND m.org_id=s.org_id JOIN workspace_meeting_members p ON p.meeting_id=m.id AND p.participant_id=-a.id WHERE s.token_hash=? AND s.expires_at>CURRENT_TIMESTAMP AND m.status NOT IN ('ENDED','CANCELLED') AND NOT EXISTS(SELECT 1 FROM agent_permission_overrides o WHERE o.actor_id=a.id AND o.permission='MEETINGS.READ' AND o.allowed=FALSE)",digest(bearer.substring(7)));
  if(rows.isEmpty()||(room!=null&&number(rows.getFirst().get("meeting_id"))!=room))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Agent session expired, revoked, or unavailable for this meeting");return rows.getFirst();
 }
 private List<Map<String,Object>> participants(long room){return jdbc.queryForList("SELECT p.participant_id AS id,CASE WHEN p.participant_id<0 THEN a.display_name ELSE CONCAT_WS(' ',u.first_name,u.last_name) END AS name,CASE WHEN p.participant_id<0 THEN 'AGENT' ELSE 'HUMAN' END AS actorType,CASE WHEN p.participant_id<0 THEN ap.designation ELSE u.email END AS subtitle,(p.last_seen>CURRENT_TIMESTAMP-INTERVAL 15 SECOND) AS online,COALESCE(v.audio_enabled,FALSE) AS audioEnabled,COALESCE(v.video_enabled,FALSE) AS videoEnabled,COALESCE(v.screen_sharing,FALSE) AS screenSharing,COALESCE(v.hand_raised,FALSE) AS handRaised FROM workspace_meeting_members p LEFT JOIN workspace_meeting_presence v ON v.meeting_id=p.meeting_id AND v.participant_id=p.participant_id LEFT JOIN user_account u ON u.id=p.participant_id LEFT JOIN workspace_actors a ON a.id=-p.participant_id LEFT JOIN workspace_agent_profiles ap ON ap.actor_id=a.id WHERE p.meeting_id=?",room);}
 private Object view(Map<String,Object> session){long room=number(session.get("meeting_id"));var value=new LinkedHashMap<>(jdbc.queryForList("SELECT * FROM workspace_meetings WHERE id=? AND org_id=?",room,session.get("org_id")).getFirst());value.put("participants",participants(room));value.put("messages",jdbc.queryForList("SELECT id,author_id AS authorId,body,created_at AS createdAt FROM workspace_meeting_messages WHERE meeting_id=? ORDER BY id DESC LIMIT 200",room));value.put("self",Map.of("id",-number(session.get("agent_id")),"name",session.get("display_name"),"actorType","AGENT"));value.put("providerConfigured",false);return value;}
 @GetMapping("/api/meeting-runtime/config") public Object config(@RequestHeader(value="Authorization",required=false)String token){session(token,null);return Map.of("iceServers",json.readValue(ice,List.class),"maxVideoParticipants",8);}
 @GetMapping("/api/meeting-runtime/{room}") public Object get(@PathVariable long room,@RequestHeader(value="Authorization",required=false)String token){return view(session(token,room));}
 @PostMapping("/api/meeting-runtime/{room}/join") @Transactional public Object join(@PathVariable long room,@RequestHeader(value="Authorization",required=false)String token){var s=session(token,room);var locked=jdbc.queryForList("SELECT status FROM workspace_meetings WHERE id=? FOR UPDATE",room);if(locked.isEmpty()||Set.of("ENDED","CANCELLED").contains(locked.getFirst().get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This meeting has ended");if(jdbc.queryForObject("SELECT COUNT(*) FROM workspace_meeting_members WHERE meeting_id=? AND participant_id<>? AND last_seen>CURRENT_TIMESTAMP-INTERVAL 15 SECOND",Integer.class,room,-number(s.get("agent_id")))>=8)throw new ResponseStatusException(HttpStatus.CONFLICT,"This peer-to-peer room supports 8 live participants");jdbc.update("UPDATE workspace_meetings SET status='LIVE' WHERE id=?",room);heartbeat(s);return view(s);}
 private void heartbeat(Map<String,Object> s){jdbc.update("UPDATE workspace_meeting_members SET last_seen=CURRENT_TIMESTAMP(6) WHERE meeting_id=? AND participant_id=?",s.get("meeting_id"),-number(s.get("agent_id")));}
 @PostMapping("/api/meeting-runtime/{room}/leave") public void leave(@PathVariable long room,@RequestHeader(value="Authorization",required=false)String token){var s=session(token,room);jdbc.update("UPDATE workspace_meeting_members SET last_seen=NULL WHERE meeting_id=? AND participant_id=?",room,-number(s.get("agent_id")));}
 @PostMapping("/api/meeting-runtime/{room}/messages") public Object message(@PathVariable long room,@RequestHeader(value="Authorization",required=false)String token,@RequestBody Map<String,Object> body){var s=session(token,room);String message=Objects.toString(body.get("message"),"").trim();if(message.isEmpty()||message.length()>20000)throw new IllegalArgumentException("Write a message up to 20000 characters");jdbc.update("INSERT INTO workspace_meeting_messages(meeting_id,author_id,body) VALUES(?,?,?)",room,-number(s.get("agent_id")),message);return view(s);}
 @GetMapping("/api/meeting-runtime/{room}/signals") public Object signals(@PathVariable long room,@RequestHeader(value="Authorization",required=false)String token,@RequestParam(defaultValue="0")long after){var s=session(token,room);heartbeat(s);var events=jdbc.queryForList("SELECT id,sender_id AS senderId,payload FROM workspace_meeting_signals WHERE meeting_id=? AND recipient_id=? AND id>? AND created_at>CURRENT_TIMESTAMP-INTERVAL 2 MINUTE ORDER BY id LIMIT 200",room,-number(s.get("agent_id")),after);for(var event:events)event.put("payload",json.readValue(event.get("payload").toString(),Map.class));return Map.of("signals",events,"participants",participants(room),"ended",false);}
 @PostMapping("/api/meeting-runtime/{room}/signals") public void signal(@PathVariable long room,@RequestHeader(value="Authorization",required=false)String token,@RequestBody Map<String,Object> body){var s=session(token,room);long from=-number(s.get("agent_id")),to=number(body.get("to"));if(to==0||to==from||jdbc.queryForObject("SELECT COUNT(*) FROM workspace_meeting_members WHERE meeting_id=? AND participant_id=?",Integer.class,room,to)!=1)throw new IllegalArgumentException("Choose an invited participant in this meeting");if(!(body.get("payload") instanceof Map<?,?> payload)||!Set.of("offer","answer","candidate").contains(payload.get("type")))throw new IllegalArgumentException("Invalid peer signal");String content=json.writeValueAsString(payload);if(content.length()>50000)throw new IllegalArgumentException("Peer signal is too large");jdbc.update("INSERT INTO workspace_meeting_signals(meeting_id,sender_id,recipient_id,payload) VALUES(?,?,?,?)",room,from,to,content);}
 @PostMapping("/api/meeting-runtime/{room}/presence")public void presence(@PathVariable long room,@RequestHeader(value="Authorization",required=false)String token,@RequestBody Map<String,Object> body){var s=session(token,room);jdbc.update("INSERT INTO workspace_meeting_presence(meeting_id,participant_id,audio_enabled,video_enabled,screen_sharing,hand_raised) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE audio_enabled=VALUES(audio_enabled),video_enabled=VALUES(video_enabled),screen_sharing=VALUES(screen_sharing),hand_raised=VALUES(hand_raised)",room,-number(s.get("agent_id")),Boolean.TRUE.equals(body.get("audioEnabled")),Boolean.TRUE.equals(body.get("videoEnabled")),Boolean.TRUE.equals(body.get("screenSharing")),Boolean.TRUE.equals(body.get("handRaised")));}
}
